vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as service from "@/server/services/issue-service";
import { issueFilterSchema } from "@/schemas/issue";
import { parseIssueFilterParams } from "@/hooks/issue-filter-params";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("adr", () => {
  it("works", async () => {
    const t = await createTenant("x");
    const a = await labelRepo.insertLabel({ orgId: t.org.id, name: "a", color: "#ef4444", description: null });
    const b = await labelRepo.insertLabel({ orgId: t.org.id, name: "b", color: "#ef4444", description: null });
    let n = 1;
    const mk = (o: any, extra: any = {}) => issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id, o), ...extra }, t.userIds.owner, n++);
    const both = await mk({ title: "both", assigneeId: t.userIds.member, dueAt: "2026-03-02T23:00:00Z" }, { labelIds: [a.id, b.id] });
    const one = await mk({ title: "one", dueAt: "2026-03-03T00:00:00.000Z" }, { labelIds: [a.id], status: "done" });
    const arch = await mk({ title: "arch" });
    await issueRepo.archiveIssue(t.org.id, arch.id);
    const base = { orgId: t.org.id, limit: 100, cursor: null };
    const ids = async (f: any) => { const p = await issueRepo.listIssues(issueFilterSchema.parse({ ...base, ...f })); expect(p.total).toBe(p.items.length); return p.items.map((i) => i.title).sort(); };
    expect(await ids({ labelIds: [a.id, b.id] })).toEqual(["both"]);
    expect(await ids({ assigneeId: null })).toEqual(["one"]);
    expect(await ids({ assigneeId: "none" })).toEqual(["one"]);
    expect(await ids({ dueBefore: "2026-03-02" })).toEqual(["both"]);
    expect(await ids({ dueBefore: "2026-03-03" })).toEqual(["both", "one"]);
    expect(await ids({ dueBefore: "2026-03-03T00:00:00Z" })).toEqual(["both"]);
    expect(await ids({ status: ["open"] })).toEqual(["both"]);
    expect(await ids({ status: ["closed"] })).toEqual(["one"]);
    expect(await ids({ includeArchived: "only" })).toEqual(["arch"]);
    expect(await ids({ includeArchived: true })).toEqual(["arch", "both", "one"]);
    const f = parseIssueFilterParams(new URLSearchParams("assignee=me&status=open&due_before=2026-03-02&archived=only"));
    expect(f).toEqual({ assigneeId: "me", status: ["backlog", "todo", "in_progress", "in_review"], dueBefore: "2026-03-02", includeArchived: "only" });
    const actor = { userId: t.userIds.member, orgId: t.org.id, role: "member" } as any;
    const p = await service.listIssues(t.actors?.member ?? actor, issueFilterSchema.parse({ ...base, assigneeId: "me" }));
    expect(p.items.map((i) => i.title)).toEqual(["both"]);
  });
});
